baseline.metadata:
- name: Download cold-install receipt matrix
  if: ${{ inputs.host != '' }}
  uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
  with:
    pattern: artifact-package-cold-*-${{ inputs.source-commit }}
    path: ${{ runner.temp }}/artifact-publication-cold
    merge-multiple: false
    run-id: ${{ inputs.ci-run-id }}
    github-token: ${{ inputs.github-token }}

current.metadata:
- name: Download cold-install receipt matrix
  if: ${{ inputs.host != '' }}
  uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
  with:
    pattern: artifact-package-cold-*-${{ inputs.source-commit }}
    path: ${{ runner.temp }}/artifact-publication-cold
    merge-multiple: false
    run-id: ${{ inputs.ci-run-id }}
    github-token: ${{ inputs.github-token }}

baseline.metadata:
- name: Verify the CI package cohort (payload digests + cold-install receipts)
  id: package
  if: ${{ inputs.host != '' }}
  shell: bash
  env:
    HOST: ${{ inputs.host }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    CI_RUN_ID: ${{ inputs.ci-run-id }}
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}

current.metadata:
- name: Verify the CI package cohort (payload digests + cold-install receipts)
  id: package
  if: ${{ inputs.host != '' }}
  shell: bash
  env:
    HOST: ${{ inputs.host }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    CI_RUN_ID: ${{ inputs.ci-run-id }}
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}

baseline.metadata:
- name: Resolve version from the manifest
  id: v
  shell: bash
  env:
    MANIFEST: ${{ inputs.manifest }}
    COMPANION: ${{ inputs.companion-manifest }}
    TAG_PREFIX: ${{ inputs.tag-prefix }}

current.metadata:
- name: Resolve version from the manifest
  id: v
  shell: bash
  env:
    MANIFEST: ${{ inputs.manifest }}
    COMPANION: ${{ inputs.companion-manifest }}
    TAG_PREFIX: ${{ inputs.tag-prefix }}

baseline.metadata:
- name: Extract the CHANGELOG section as release notes
  shell: bash
  env:
    VER: ${{ steps.v.outputs.version }}
    TAG: ${{ steps.v.outputs.tag }}
    CHANGELOG: ${{ inputs.changelog }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

current.metadata:
- name: Extract the CHANGELOG section as release notes
  shell: bash
  env:
    VER: ${{ steps.v.outputs.version }}
    TAG: ${{ steps.v.outputs.tag }}
    CHANGELOG: ${{ inputs.changelog }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

baseline.metadata:
- name: Observe remote state and plan
  id: plan
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    ASSET: ${{ steps.package.outputs.file }}

current.metadata:
- name: Observe remote state and plan
  id: plan
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TARGET: ${{ inputs.target }}
    VERSION: ${{ steps.v.outputs.version }}
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    ASSET: ${{ steps.package.outputs.file }}
    ASSET_SHA256: ${{ steps.package.outputs.sha256 }}

baseline.metadata:
- name: Select the exact Pi npm tarball
  id: pi
  if: ${{ inputs.host == 'pi' }}
  shell: bash
  env:
    VERSION: ${{ steps.v.outputs.version }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    CI_RUN_ID: ${{ inputs.ci-run-id }}
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}

current.metadata:
- name: Select the exact Pi npm tarball
  id: pi
  if: ${{ inputs.host == 'pi' }}
  shell: bash
  env:
    VERSION: ${{ steps.v.outputs.version }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    CI_RUN_ID: ${{ inputs.ci-run-id }}
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}

- name: Require exact major-program readiness before publication effects
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    CI_RUN_ID: ${{ inputs.ci-run-id }}
    TARGET: ${{ inputs.target }}
    VERSION: ${{ steps.v.outputs.version }}
    EFFECTS: ${{ steps.plan.outputs.effects }}

baseline.metadata:
- name: Require matching Pi npm provenance commit
  if: ${{ inputs.host == 'pi' && steps.pi.outputs.skip != 'true' }}
  shell: bash
  env:
    SOURCE_COMMIT: ${{ inputs.source-commit }}

current.metadata:
- name: Require matching Pi npm provenance commit
  if: ${{ inputs.host == 'pi' && steps.pi.outputs.skip != 'true' }}
  shell: bash
  env:
    SOURCE_COMMIT: ${{ inputs.source-commit }}

baseline.metadata:
- name: Create and push the annotated tag
  if: ${{ steps.plan.outputs.tag == 'create' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

current.metadata:
- name: Create and push the annotated tag
  if: ${{ steps.plan.outputs.tag == 'create' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

baseline.metadata:
- name: Read back the tag
  shell: bash
  env:
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

current.metadata:
- name: Read back the tag
  shell: bash
  env:
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

baseline.metadata:
- name: Capture published tag identity receipt
  id: receipt
  if: ${{ always() && steps.v.outputs.tag != '' && steps.plan.outcome != 'skipped' }}
  shell: bash
  env:
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    RECEIPT_PATH: ${{ runner.temp }}/tag-publication-${{ github.job }}-${{ github.run_attempt }}.json

current.metadata:
- name: Capture published tag identity receipt
  id: receipt
  if: ${{ always() && steps.v.outputs.tag != '' && steps.plan.outcome != 'skipped' }}
  shell: bash
  env:
    TAG: ${{ steps.v.outputs.tag }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    RECEIPT_PATH: ${{ runner.temp }}/tag-publication-${{ github.job }}-${{ github.run_attempt }}.json

baseline.metadata:
- name: Create the draft Release
  id: draft
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    TITLE: ${{ inputs.title-prefix }} ${{ steps.v.outputs.version }}
    STATE: ${{ steps.plan.outputs.release }}
    RELEASE_ID: ${{ steps.plan.outputs.release-id }}

current.metadata:
- name: Create the draft Release
  id: draft
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    TITLE: ${{ inputs.title-prefix }} ${{ steps.v.outputs.version }}
    STATE: ${{ steps.plan.outputs.release }}
    RELEASE_ID: ${{ steps.plan.outputs.release-id }}

baseline.metadata:
- name: Upload and read back the package asset
  if: ${{ inputs.host == 'claude' || inputs.host == 'codex' || inputs.host == 'pi' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    RELEASE_ID: ${{ steps.draft.outputs.release-id }}
    MISSING: ${{ steps.plan.outputs.missing-assets }}
    ASSET_FILE: ${{ steps.package.outputs.file }}
    ASSET_PATH: ${{ steps.package.outputs.path }}
    ASSET_SHA256: ${{ steps.package.outputs.sha256 }}

current.metadata:
- name: Upload and read back the package asset
  if: ${{ inputs.host == 'claude' || inputs.host == 'codex' || inputs.host == 'pi' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    RELEASE_ID: ${{ steps.draft.outputs.release-id }}
    MISSING: ${{ steps.plan.outputs.missing-assets }}
    ASSET_FILE: ${{ steps.package.outputs.file }}
    ASSET_PATH: ${{ steps.package.outputs.path }}
    ASSET_SHA256: ${{ steps.package.outputs.sha256 }}

baseline.metadata:
- name: Publish the Claude marketplace channel
  id: claude-channel
  if: ${{ inputs.host == 'claude' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    COHORT_SHA256: ${{ steps.package.outputs.cohort-sha256 }}
    VERSION: ${{ steps.v.outputs.version }}

current.metadata:
- name: Publish the Claude marketplace channel
  id: claude-channel
  if: ${{ inputs.host == 'claude' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    COHORT_SHA256: ${{ steps.package.outputs.cohort-sha256 }}
    VERSION: ${{ steps.v.outputs.version }}
    EFFECTS: ${{ steps.plan.outputs.effects }}

baseline.metadata:
- name: Audit Codex distribution rulesets (advisory)
  if: ${{ inputs.host == 'codex' && inputs.codex-ruleset-verifier-token != '' }}
  continue-on-error: true
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.codex-ruleset-verifier-token }}

current.metadata:
- name: Audit Codex distribution rulesets (advisory)
  if: ${{ inputs.host == 'codex' && inputs.codex-ruleset-verifier-token != '' }}
  continue-on-error: true
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.codex-ruleset-verifier-token }}

baseline.metadata:
- name: Publish the Codex marketplace channel
  id: codex-channel
  if: ${{ inputs.host == 'codex' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    COHORT_SHA256: ${{ steps.package.outputs.cohort-sha256 }}
    VERSION: ${{ steps.v.outputs.version }}

current.metadata:
- name: Publish the Codex marketplace channel
  id: codex-channel
  if: ${{ inputs.host == 'codex' }}
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    COHORT_SHA256: ${{ steps.package.outputs.cohort-sha256 }}
    VERSION: ${{ steps.v.outputs.version }}
    EFFECTS: ${{ steps.plan.outputs.effects }}

baseline.metadata:
- name: Publish @arbiterforge/ca-pi to npm
  if: ${{ inputs.host == 'pi' && steps.pi.outputs.skip != 'true' }}
  shell: bash
  env:
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}
    TARBALL: ${{ steps.pi.outputs.tarball }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

current.metadata:
- name: Publish @arbiterforge/ca-pi to npm
  if: ${{ inputs.host == 'pi' && steps.pi.outputs.skip != 'true' && contains(steps.plan.outputs.effects, 'channel') }}
  shell: bash
  env:
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}
    TARBALL: ${{ steps.pi.outputs.tarball }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

baseline.metadata:
- name: Read back the npm publication
  if: ${{ inputs.host == 'pi' }}
  shell: bash
  env:
    VERSION: ${{ steps.v.outputs.version }}
    INTEGRITY: ${{ steps.pi.outputs.integrity }}
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

current.metadata:
- name: Read back the npm publication
  if: ${{ inputs.host == 'pi' }}
  shell: bash
  env:
    VERSION: ${{ steps.v.outputs.version }}
    INTEGRITY: ${{ steps.pi.outputs.integrity }}
    NPM_CLI: ${{ steps.npm-cli.outputs.executable }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}

baseline.metadata:
- name: Publish the Release
  id: finish
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    RELEASE_ID: ${{ steps.draft.outputs.release-id }}
    MARK_LATEST: ${{ inputs.mark-latest }}

current.metadata:
- name: Publish the Release
  id: finish
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    TAG: ${{ steps.v.outputs.tag }}
    RELEASE_ID: ${{ steps.draft.outputs.release-id }}
    MARK_LATEST: ${{ inputs.mark-latest }}

baseline.metadata:
- name: Attach the publication receipt
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    RELEASE_ID: ${{ steps.draft.outputs.release-id }}
    MISSING: ${{ steps.plan.outputs.missing-assets }}
    TARGET: ${{ inputs.target }}
    HOST: ${{ inputs.host }}
    TAG: ${{ steps.v.outputs.tag }}
    VERSION: ${{ steps.v.outputs.version }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    PACKAGE_FILE: ${{ inputs.host == 'pi' && steps.pi.outputs.tarball || steps.package.outputs.file }}
    PACKAGE_SHA256: ${{ steps.package.outputs.sha256 }}
    CHANNEL_REF: ${{ steps.claude-channel.outputs.ref || steps.codex-channel.outputs.ref }}

current.metadata:
- name: Attach the publication receipt
  shell: bash
  env:
    GH_TOKEN: ${{ inputs.github-token }}
    RELEASE_ID: ${{ steps.draft.outputs.release-id }}
    MISSING: ${{ steps.plan.outputs.missing-assets }}
    TARGET: ${{ inputs.target }}
    HOST: ${{ inputs.host }}
    TAG: ${{ steps.v.outputs.tag }}
    VERSION: ${{ steps.v.outputs.version }}
    SOURCE_COMMIT: ${{ inputs.source-commit }}
    PACKAGE_FILE: ${{ inputs.host == 'pi' && steps.pi.outputs.tarball || steps.package.outputs.file }}
    PACKAGE_SHA256: ${{ steps.package.outputs.sha256 }}
    CHANNEL_REF: ${{ steps.claude-channel.outputs.ref || steps.codex-channel.outputs.ref }}
